def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out"""
    # Find first difference
    min_len = min(len(s_in), len(s_out))

    # Look for insertion/deletion patterns
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Check what's being inserted/changed
            # Try to find pattern by looking at context

            # Check if we're inserting characters
            if len(s_in) < len(s_out):
                # Insertion case - find what was inserted
                # Check if s_out[i:i+3] matches some pattern in s_in
                return (s_in[i], s_out[i:i+3], i)
            else:
                # Substitution case
                return (s_in[i], s_out[i], i)

    # If we reach here, check if it's length change
    if len(s_in) < len(s_out):
        # Insertion at end or middle
        return (s_in[-1] if s_in else "", s_out[len(s_in):], len(s_in))
    elif len(s_in) > len(s_out):
        # Deletion
        return (s_in[len(s_out):], "", len(s_out))
    else:
        return ("", "", -1)

